package mtc

import (
	"encoding/hex"
	"encoding/pem"
	"os"
	"testing"

	"github.com/zmap/zcrypto/x509"
)

// TestSubtreeHash checks the subtree hashes of certificates generated by
// Magnolia (geomys.org/magnolia/internal/mtc), whose test computes the
// expected hashes with an independent Merkle tree implementation.
func TestSubtreeHash(t *testing.T) {
	for _, tt := range []struct {
		file, hash string
	}{
		{"mtc_magnolia_standalone.pem", "6b6bd16470622739efdb991d36032f21ed1eb2b6a7767495b9318fa8c49eb7cf"},
		{"mtc_magnolia_landmark.pem", "2ac543a47ee717c21d1163f8ccd5356753f9881139571a9378b4562c704e2bb4"},
	} {
		t.Run(tt.file, func(t *testing.T) {
			data, err := os.ReadFile("../testdata/" + tt.file)
			if err != nil {
				t.Fatal(err)
			}
			block, _ := pem.Decode(data)
			if block == nil {
				t.Fatal("failed to decode PEM")
			}
			c, err := x509.ParseCertificate(block.Bytes)
			if err != nil {
				t.Fatal(err)
			}
			parsed, err := ParseCertificate(c)
			if err != nil {
				t.Fatal(err)
			}
			if err := ValidateSelfContained(c, parsed); err != nil {
				t.Fatal(err)
			}
			got, err := subtreeHash(c, parsed)
			if err != nil {
				t.Fatal(err)
			}
			if hex.EncodeToString(got[:]) != tt.hash {
				t.Errorf("subtree hash = %x, want %s", got, tt.hash)
			}
		})
	}
}
